import subprocess,json,re
def execute(interface,output):
    if not isinstance(interface,str) or not re.fullmatch(r'[A-Za-z0-9_.:-]{1,15}',interface):raise ValueError('invalid interface name')
    result=subprocess.run(['ip','-j','link','show','dev',interface],text=True,capture_output=True,timeout=2)
    if result.returncode:raise ValueError('interface not found')
    rows=json.loads(result.stdout)
    if len(rows)!=1 or rows[0].get('ifname')!=interface:raise ValueError('unexpected interface result')
    row=rows[0];kind=row.get('link_type');address=None
    if kind=='ether':
        address=row.get('address','').lower()
        if not re.fullmatch(r'(?:[0-9a-f]{2}:){5}[0-9a-f]{2}',address):raise ValueError('invalid Ethernet address')
    value={'interface':interface,'link_type':kind,'mac':address}
    publish(output,json.dumps(value,ensure_ascii=False,indent=2).encode())
    return value
```

原理补充：
MAC 地址用于链路层标识接口，交换机按目的 MAC 转发本地二层帧。常见以太网地址为 48 位，但并不证明设备身份永远唯一或不可更改。跨路由跳转时二层头会重写，远端目的 IP 不会直接作为本地目的 MAC。

