import json,re,ipaddress,struct
def execute(source,output):
    if pathlib.Path(source).resolve()==pathlib.Path(output).resolve():raise ValueError('input/output must differ')
    obj=json.loads(pathlib.Path(source).read_text())
    if not isinstance(obj,dict):raise ValueError('object required')
    mac=obj.get('source_mac')
    if not isinstance(mac,str) or not re.fullmatch(r'(?:[0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}',mac):raise ValueError('six-byte MAC required')
    sender=bytes.fromhex(mac.replace(':',''))
    if sender==bytes(6) or sender[0]&1:raise ValueError('nonzero unicast source MAC required')
    try:source_ip=ipaddress.IPv4Address(obj.get('source_ip'));target_ip=ipaddress.IPv4Address(obj.get('target_ip'))
    except (ValueError,TypeError) as e:raise ValueError('IPv4 addresses required') from e
    if not isinstance(obj.get('source_ip'),str) or not isinstance(obj.get('target_ip'),str):raise ValueError('text IPv4 required')
    for address in [source_ip,target_ip]:
        if address.is_unspecified or address.is_multicast or address==ipaddress.IPv4Address('255.255.255.255'):raise ValueError('concrete IPv4 unicast address required')
    ethernet=bytes.fromhex('ffffffffffff')+sender+bytes.fromhex('0806')
    request=struct.pack('!HHBBH',1,0x0800,6,4,1)+sender+source_ip.packed+bytes(6)+target_ip.packed
    frame=ethernet+request
    frame+=bytes(max(0,60-len(frame))) # Ethernet minimum excluding preamble and FCS.
    publish(output,frame)
    return len(frame)
```

原理补充：
ff:ff:ff:ff:ff:ff 是以太网广播目的地址，帧会在当前广播域传播，例如 IPv4 ARP 请求。路由器通常不把这种二层广播原样转发到其他广播域；不能当作某一台主机的单播地址。

